{
  "item_id": "PRISMA_2020_3",
  "elements": [
    {
      "element_id": "prisma_2020_3_e1",
      "status": "PRESENT",
      "chunk_id": "text_3",
      "quote": "The use of Point-of-care ultrasound (PoCUS) has gained increasing popularity in several domains of acute patient management, including acute onset dyspnea [11, 15]. There is an increasing body of evidence demonstrating that the accuracy of PoCUS is comparable to the current imaging reference standard CXR in general [16] as well as in specific conditions, such as pneumonia [17], acute decompensated heart failure [16], pleural effusion [18], pneumothorax [19] and pulmonary embolism [20]. PoCUS has other advantages, such as being free from ionizing radiation, and most importantly can be performed in real-time at the bedside [16, 21]. Additionally, PoCUS can answer a broad spectrum of remaining diagnostic questions and may also help to optimize and personalize therapy [22]. However, very few trials have examined meaningful clinical outcomes related to PoCUS usage to date [23] and the results on outcome measurements were heterogeneous [24].",
      "reason": "Describes existing evidence on PoCUS accuracy/advantages and highlights uncertainties/knowledge gaps regarding clinical outcomes and heterogeneity."
    },
    {
      "element_id": "prisma_2020_3_e2",
      "status": "PRESENT",
      "chunk_id": "text_4",
      "quote": "Therefore, rapid and appropriate diagnosis of the underlying pathology is of utmost importance for prompt and adequate treatment [9]. However, differential diagnosis is often challenging [10, 11]. Most physicians mainly rely on conventional diagnostic modalities, such as medical history, physical examination, chest X-ray (CXR), electrocardiogram (ECG), and standard laboratory tests [12]. Even given all these tests, some studies have raised doubts about the diagnostic accuracy of these conventional approaches, especially in the critically ill patient population [13, 14]. Therefore, we conducted a high-quality, comprehensive systematic review and meta-analysis that included the most recent publications that reported clinical outcomes with the use of PoCUS in patients who developed acute onset dyspnea.",
      "reason": "Explains why a review is needed: acute-onset dyspnea diagnosis is important but challenging, conventional modalities may have diagnostic accuracy doubts, and PoCUS clinical outcome evidence requires synthesis."
    },
    {
      "element_id": "prisma_2020_3_e3",
      "status": "PRESENT",
      "chunk_id": "text_19",
      "quote": "In contrast to previous reviews and meta-analyses [16-20, 60] that analyzed data from patients with an explicit diagnosis, such as pneumonia or acute decompensated heart failure [9, 10, 16, 17, 62], we applied a broader definition of dyspnea, thereby including more patients and providing more comprehensive results.",
      "reason": "Identifies prior reviews/meta-analyses and explains the need for the current review by stating it differs through a broader dyspnea definition and includes more patients."
    },
    {
      "element_id": "prisma_2020_3_e4",
      "status": "MISSING",
      "chunk_id": null,
      "quote": null,
      "reason": "No explicit description of a proposed mechanism of action of PoCUS (for intervention effects) is provided in the retrieved evidence."
    },
    {
      "element_id": "prisma_2020_3_e5",
      "status": "MISSING",
      "chunk_id": null,
      "quote": null,
      "reason": "No logic model or hypothesised relationships between PoCUS components and outcomes are presented in the retrieved evidence."
    }
  ],
  "confidence": 78
}

{
